INSERT INTO work_queue (id,task_type,payload,status,created_at) SELECT 'pending-backfill-guard','metadata','{}','guard_failed',unixepoch() WHERE NOT ((SELECT COUNT(*) FROM c JOIN song_masters sm ON sm.id=c.master_id AND sm.album_id='pending-uploads' AND sm.title IS c.title_snapshot AND sm.disc IS c.disc_snapshot AND sm.track IS c.track_snapshot JOIN song_instances si ON si.id=c.instance_id AND si.master_id=sm.id AND si.source_id='r2-local' AND si.source_type='original' AND si.missing=0 AND si.tag_scanned=1 AND lower(si.suffix)='wav' AND si.storage_object_id=c.object_id JOIN storage_entries se ON se.id=c.entry_id AND se.instance_id=si.id AND se.kind='file' AND se.source_id='r2-local' AND se.parent_id='se-8207e3d583784b0f8e464dbb500f28bd' AND se.object_id=si.storage_object_id JOIN storage_objects so ON so.id=c.object_id WHERE (SELECT COUNT(*) FROM storage_entries f WHERE f.instance_id=si.id AND f.kind='file')=1)=16 AND NOT EXISTS (SELECT 1 FROM albums WHERE id='al-379190d71773f7eda5c8e71260f1e1a8') AND NOT EXISTS (SELECT 1 FROM song_masters WHERE id IN ('sm-upload-0796f5d3-fd3','sm-upload-0d698ddd-586','sm-upload-34a4e79c-3ac','sm-upload-3e4a3e0c-5e1','sm-upload-412884aa-3c6','sm-upload-5189133a-af2','sm-upload-55fa915d-2e6','sm-upload-642c5555-32e','sm-upload-68e21ac4-af0','sm-upload-962f69d3-a47','sm-upload-be4c6092-980','sm-upload-c823de32-b12','sm-upload-d38bae55-e32','sm-upload-d4898d69-3e7','sm-upload-d9e8676f-0f4','sm-upload-e258a0c1-196') GROUP BY lower(trim(title)) HAVING COUNT(*)>1) AND NOT EXISTS (SELECT 1 FROM song_masters WHERE id IN ('sm-upload-0796f5d3-fd3','sm-upload-0d698ddd-586','sm-upload-34a4e79c-3ac','sm-upload-3e4a3e0c-5e1','sm-upload-412884aa-3c6','sm-upload-5189133a-af2','sm-upload-55fa915d-2e6','sm-upload-642c5555-32e','sm-upload-68e21ac4-af0','sm-upload-962f69d3-a47','sm-upload-be4c6092-980','sm-upload-c823de32-b12','sm-upload-d38bae55-e32','sm-upload-d4898d69-3e7','sm-upload-d9e8676f-0f4','sm-upload-e258a0c1-196') AND track IS NOT NULL GROUP